Dataspatium.assets.register("presets/api/raa-arkreg.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"raa-arkreg\",\n  \"name\": \"Riksantikvarieämbetet fornlämningar (WFS)\",\n  \"publisher\": \"Riksantikvarieämbetet\",\n  \"description\": \"Kulturmiljöregistrets lämningar (Fornsök) som geodata från Riksantikvarieämbetet. Välj lager och hämta objekten; begränsa med ett område.\",\n  \"docs\": \"https://www.raa.se/hitta-information/fornsok/\",\n  \"license\": {\n    \"name\": \"Öppna data (RAÄ)\",\n    \"url\": \"https://www.raa.se/hitta-information/oppna-data/\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://karta.raa.se/geo/arkreg_v1.0/ows\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Swedish National Heritage Board ancient remains (WFS)\",\n      \"description\": \"The remains of the cultural heritage register (Fornsök) as geodata. Choose a layer and fetch the features; limit by an area.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Riksantikvarieämbetet fortidsminder (WFS)\",\n      \"description\": \"Kulturmiljøregistrets fortidsminder (Fornsök) som geodata fra Riksantikvarieämbetet. Vælg et lag og hent objekterne; begræns med et område.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Riksantikvarieämbetet kulturminner (WFS)\",\n      \"description\": \"Kulturmiljøregisterets kulturminner (Fornsök) som geodata fra Riksantikvarieämbetet. Velg et lag og hent objektene; begrens med et område.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Riksantikvarieämbetet muinaisjäännökset (WFS)\",\n      \"description\": \"Kulttuuriympäristörekisterin muinaisjäännökset (Fornsök) paikkatietona Riksantikvarieämbetetiltä. Valitse taso ja nouda kohteet; rajaa alueella.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Fornminjar Riksantikvarieämbetet (WFS)\",\n      \"description\": \"Fornminjar menningarumhverfisskrárinnar (Fornsök) sem landupplýsingar frá Riksantikvarieämbetet. Veldu lag og sæktu fitjurnar; takmarkaðu við svæði.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
